"""Verify the final build-alias rejection leaves all accepted generated bytes unchanged."""
from pathlib import Path
import hashlib
import json
import sys

ROOT = Path(__file__).resolve().parents[4]
SCG = ROOT / 'apps/SCG'
sys.path.insert(0, str(SCG / 'src'))
from silverstar_fccg.app.usb_transport import _Project_Read, UsbTransport_Plan
from silverstar_fccg.generator.usb_cdc_integration import UsbCdcIntegration_Render

HERE = Path(__file__).resolve().parent
WORK = ROOT / '.work/0.1.3-software-completion-20261101'


def Main():
    rows = []
    for part in ('f103', 'f407'):
        native = Path('D:/Codex_Work/2026-10-08/task/usb-validation') / ('cube-' + part + '-usb')
        files = _Project_Read(native)
        plan = UsbTransport_Plan(native)
        assert not plan.reasons, plan.reasons
        current = UsbCdcIntegration_Render(files, plan.owners)
        built = WORK / 'usb/generic-after-v1/native' / part
        differences = [name for name, data in current.items() if data != (built / name).read_bytes()]
        assert not differences, differences
        rows.append({'part': part, 'generated_files_compared': len(current), 'changed': differences,
                     'sha256': {name: hashlib.sha256(data).hexdigest() for name, data in current.items()}})
    sources = ['src/silverstar_fccg/generator/usb_cdc_integration.py', 'tests/test_usb_transport_integration.py']
    receipt = {'scope': 'Final additional build-owner alias rejection only; accepted full generated byte equality against actual ARM/analyzer candidate',
               'rows': rows, 'source_sha256': {name: hashlib.sha256((SCG / name).read_bytes()).hexdigest() for name in sources}}
    (HERE / 'admission-revision.json').write_text(json.dumps(receipt, indent=2) + '\n', encoding='utf8')
    for epoch in ('generic-alias-before-v1', 'generic-alias-after-v1'):
        for suffix in ('.log', '.exit'):
            source = WORK / ('usb-' + epoch + suffix)
            (HERE / (epoch + suffix)).write_bytes(source.read_bytes())
    print('PASS: accepted generated files remain byte-identical', [(r['part'], r['generated_files_compared']) for r in rows])


if __name__ == '__main__':
    Main()
